"use strict";(self.webpackChunkbast_docu=self.webpackChunkbast_docu||[]).push([[235],{88817:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"beta-26.3","metadata":{"permalink":"/dadadocu/dadaprogressions-changelog/beta-26.3","source":"@site/dadaprogressions-changelog/2026-07-08-beta-26.3.md","title":"DadaProgressions Beta 26.3","description":"Beta 26.3 finishes the point-rule editor and improves event debugging.","date":"2026-07-08T00:00:00.000Z","tags":[{"inline":true,"label":"dadaprogressions","permalink":"/dadadocu/dadaprogressions-changelog/tags/dadaprogressions"}],"hasTruncateMarker":true,"authors":[{"name":"mrbast","title":"DadaProgressions Developer","url":"https://www.spigotmc.org/members/mrbast.610454/","key":"mrbast","page":null}],"frontMatter":{"slug":"beta-26.3","title":"DadaProgressions Beta 26.3","authors":["mrbast"],"tags":["dadaprogressions"]},"unlisted":false,"nextItem":{"title":"DadaProgressions Beta 26.2","permalink":"/dadadocu/dadaprogressions-changelog/beta-26.2"}},"content":"Beta 26.3 finishes the point-rule editor and improves event debugging.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Point rules\\n\\nEach rule can now have its own `when-mode: ALL|ANY`.\\n\\n```yaml\\n- when-mode: ALL\\n  when:\\n    material: [DIAMOND_ORE]\\n    world: [survival]\\n  set: 10\\n```\\n\\n`ALL` requires both conditions; `ANY` requires only one. Rules are checked from top to bottom and the first match wins. Old rules still default to `ALL`.\\n\\n## Editor\\n\\nThe point screen can change the base amount, rounding, operation, value, conditions and rule order. It supports both `SET` and `MULTIPLY` rules.\\n\\n## Debug\\n\\nThe debug output now shows which point rule won and the calculation from base to final points.\\n\\n```text\\n/dp admin debug <goalId> <onlinePlayer> [timeoutSeconds]\\n/dp admin debug cancel <onlinePlayer>\\n```\\n\\nThe timeout is 60 seconds by default and accepts values from 5 to 600.\\n\\n## YAML schema\\n\\nA JSON Schema for goal files is included for autocomplete and basic checks in IntelliJ and other compatible editors."},{"id":"beta-26.2","metadata":{"permalink":"/dadadocu/dadaprogressions-changelog/beta-26.2","source":"@site/dadaprogressions-changelog/2026-07-04-beta-26.2.md","title":"DadaProgressions Beta 26.2","description":"Beta 26.2 makes complex goals easier to edit and debug.","date":"2026-07-04T00:00:00.000Z","tags":[{"inline":true,"label":"dadaprogressions","permalink":"/dadadocu/dadaprogressions-changelog/tags/dadaprogressions"}],"hasTruncateMarker":true,"authors":[{"name":"mrbast","title":"DadaProgressions Developer","url":"https://www.spigotmc.org/members/mrbast.610454/","key":"mrbast","page":null}],"frontMatter":{"slug":"beta-26.2","title":"DadaProgressions Beta 26.2","authors":["mrbast"],"tags":["dadaprogressions"]},"unlisted":false,"prevItem":{"title":"DadaProgressions Beta 26.3","permalink":"/dadadocu/dadaprogressions-changelog/beta-26.3"},"nextItem":{"title":"DadaProgressions Beta 26.1","permalink":"/dadadocu/dadaprogressions-changelog/beta-26.1"}},"content":"Beta 26.2 makes complex goals easier to edit and debug.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Filters\\n\\nFilter groups now support `filter-mode: ALL` and `filter-mode: ANY`, both on the goal and on individual criteria.\\n\\nNew filters:\\n\\n- `biome`\\n- `min-y` / `max-y`\\n- `min-amount` / `max-amount`\\n\\n`include` is the allow-list and `exclude` is the veto-list. If the same value appears in both, `exclude` wins.\\n\\n## Editor\\n\\n`/dp admin editor` can now manage goals, composite criteria, filters and prerequisites. Numeric values use a keypad; known values such as materials, entities and worlds use paginated selectors.\\n\\nChanges are validated before they are kept. If something is invalid, the previous file and active configuration are restored.\\n\\n## Debug and validation\\n\\nUse this command before performing an action with the selected player:\\n\\n```text\\n/dp admin debug <goalId> <onlinePlayer>\\n```\\n\\nIt shows the real event values, filter results, points, prerequisites and cooldown.\\n\\n`/dp admin validate` checks the files without loading them. `/dp admin reload` now keeps the previous working goals if a new file is broken."},{"id":"beta-26.1","metadata":{"permalink":"/dadadocu/dadaprogressions-changelog/beta-26.1","source":"@site/dadaprogressions-changelog/2026-07-01-beta-26.1.md","title":"DadaProgressions Beta 26.1","description":"Beta 26.1 adds modular goals and cleans up notifications.","date":"2026-07-01T00:00:00.000Z","tags":[{"inline":true,"label":"dadaprogressions","permalink":"/dadadocu/dadaprogressions-changelog/tags/dadaprogressions"}],"hasTruncateMarker":true,"authors":[{"name":"mrbast","title":"DadaProgressions Developer","url":"https://www.spigotmc.org/members/mrbast.610454/","key":"mrbast","page":null}],"frontMatter":{"slug":"beta-26.1","title":"DadaProgressions Beta 26.1","authors":["mrbast"],"tags":["dadaprogressions"]},"unlisted":false,"prevItem":{"title":"DadaProgressions Beta 26.2","permalink":"/dadadocu/dadaprogressions-changelog/beta-26.2"}},"content":"Beta 26.1 adds modular goals and cleans up notifications.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Goals\\n\\n- Goals can contain several criteria joined with `AND` or `OR`.\\n- Each criterion keeps its own progress.\\n- Added filters for materials, entities, worlds, game modes, permissions, commands, damage causes and attribution.\\n- Point rules can assign fixed values or multipliers.\\n- Goals can require another goal to be completed, either in the current period or at any time in the past.\\n- Animal breeding is now tracked automatically, including on older server versions.\\n\\nThe default files include a few community goals that use the new system. Existing simple goals still work as before.\\n\\n## Notifications\\n\\nChat, action bar, title and boss bar now have separate queues. Repeated updates are grouped instead of sending a message for every single action.\\n\\nChat can also combine updates from different goals into one line. Timing, queue size and channel limits remain configurable.\\n\\n## GUI\\n\\nGoal entries now show the actual objective and useful progress values. The longer technical state text is hidden by default and can be restored with `gui.list.goal-item.show-state-lore`."}]}}')}}]);